/* 9. CTAS */
evaluate '1. CTAS preserves Float NUMERIC column type and all rows';
DROP TABLE IF EXISTS t1;
DROP TABLE IF EXISTS t2;
CREATE TABLE t1 (col1 NUMERIC);
CREATE INDEX idx_01 ON t1(col1);

SHOW CREATE TABLE t1;

